  `account` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '源站账号标识',
  `org_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '机构/公司名称',
  `intro` text COLLATE utf8mb4_unicode_ci COMMENT '公司箢??,
  `detail_info` mediumtext COLLATE utf8mb4_unicode_ci COMMENT '详细信息（点击公司后详情页）',
  `label` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '标签（如专业服务机构＿,
  `user_type` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '源站 userType',
  `logo_file_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '源站 logo 文件 id',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT '排序',
  `source_site` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'szte.com' COMMENT '数据来源站点',
  `source_api` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '来源接口',
  `fetched_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '抓取时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_account` (`account`),
  KEY `idx_org_name` (`org_name`)
) ENGINE=InnoDB AUTO_INCREMENT=18 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='知识产权融资信息服务-专业服务机构（银行融资）';
/*!40101 SET character_set_client = @saved_cs_client */;

