INSERT INTO `ip_service_org` VALUES (1,'zhanglianlian','武汉顺海企业管理咨询有限公司','顺海咨询成立亿008年，主要业务范围为客户提供战略与并购重组、知识产权管理和运营、市场营锢??项目管理??价值评估等咨询服务，同时向客户提供上市业务的相关培训??顺海咨询依托中南财经政法大学企业价墣?研究中心的深厚学术研究积淀，结合数十年来服务中小企业的实操经验，创造梣§地推出了企业智能化无形资产价墣?评价服务平台??会评网（无形资产智评系统SCVPA）??会评网在颣?过无形资产学习、无形资产比较??内在价值评估??有形资产剥离及无形资产解析五个步骤，为待评企业提供无形资产画像及估值服务??顺海咨询子公司智海科技拥有会评网全部知识产权（无形资产智能评估系统，计算机软件著作权登记证书登记号＿022SR1094468;上市公司无形资产数据库系统，计算机软件著作权登记证书登记号：2022SE1107243）??,NULL,'专业服务机构','service','1610597783310569472',1,'szte.com','https://www.szte.com/pubsapi/officialSiteApi/intellectualProperty/zyrz/user/get/2','2026-07-30 15:42:28','2026-07-30 15:42:28'),(2,'king-w','深圳市乾德投资发展有限公叿,'乾德投资是一家在产业政策、行业发展和企业经营研究、咨诿￠て??资的专业机构，近年聚焦在股权投资管理咨询方面的增值服务和早期投资，在投资管理咨询服务中建立了丢??有效的经营增墣?方法，对创业公司的发展战略、经营增值??管理优化等领域中有其独特的观察视角与解决方法??,NULL,'专业服务机构','service','1612420608241569792',2,'szte.com','https://www.szte.com/pubsapi/officialSiteApi/intellectualProperty/zyrz/user/get/2','2026-07-30 15:42:28','2026-07-30 15:42:28'),(3,'kewei','科威国际抢?ˉ转移有限公叿,'2001广月，为应对全球经济一体化和科学技术国际化的严峻挑战，积极利用国际资源，更广泛地开展国内外科技合作，清华大学专门成立\"清华大学国际抢?ˉ转移中心\"，开展国际技术转移，组织国外抢?ˉ资源与国内产业界的对接?2002广月，为了更有效地弢??清华大学的国际抢?ˉ转移工作，清华大学发起成立了??科威国际技术转移有限公司??，并委托科威公司开展清华大学国际技术转移中心的商业化运作??科威公司积极为经济发展服务，颣?过多层次??多形式、多渠道的科抢??作形式，成为清华大学服务社会和国家发展战略的一个有力的支撑平台?科威公司是科抢?¨认定的首批国家抢?ˉ转移机构，较早以市场化方式运作的国际技术转移与抢?ˉ商业化服务机构。公司以生物化工、节能环保??医疗器械等产业领域为关注重点，在全球范围内弢??技术本地化、技术商业化、技术引进与出口?我们秉承“专业化、国际化、信息化”的理念，依托丰富的国内外资源??渠道??专家以及专业化的技术经理人队伍，成功完成了多个服务案例，积累了丰富的经验，不仅在国内技术转移行业中保持了领先的地位，也在国际技术转移舞台上形成了很高的知名度??目前，我们是首批国家级抢?ˉ转移中心??首批??国家技术转移示范机构????中国科抢?¨火炬中心??国际科抢??作依托机构”????中国创新驿站??秘书处的运营单位和北京市科学技术委员会认定“首都科抢??件平台清华大学研发实验服务基地”??,NULL,'专业服务机构','service','1583339586623508480',3,'szte.com','https://www.szte.com/pubsapi/officialSiteApi/intellectualProperty/zyrz/user/get/2','2026-07-30 15:42:28','2026-07-30 15:42:28'),(4,'xinda','广东信达律师事务扢?'信达亿993年在深圳设立，是深圳市最早获得批准设立的合伙制律师事务所，也是中国最早设立的合伙制律师事务所之一。经过近30年的稳健发展，信达已成为以资本市场业务为核心，围绕资本市场客户需求，提供丢??式法律服务的综合梣§律师事务所?信达现有员工超过300名，合伙人近60名，律师和律师助理超迿00名??信达执业律师中，超迿0名律师执丿0年以上??信达律师拥有良好的教育背景