DROP TABLE IF EXISTS `platform_base`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `platform_base` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键',
  `serial_no` int NOT NULL COMMENT '序号',
  `platform_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '平台名称',
  `platform_type` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '平台类型（概念验证中忿中小试基地）',
  `support_unit` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '依托单位',
  `platform_fun` text COLLATE utf8mb4_unicode_ci COMMENT '平台功能',
  `contact_person` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '联系亿,
  `contact_mobile` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '联系方式',
